  "Harvested but not in the plan, so not compared: {names}.": {"st":"Di kotutswe empa ha di moralong, ka hona ha di a bapiswa: {names}.","ve":"Zwo kaṋwaho fhedzi zwi sa ho kha pulane, ngauralo a zwo ngo vhambedzwa: {names}.","ts":"Swi tshoveriwile kambe a swi ri eka pulani, hikwalaho a swi ringanisiwanga: {names}."},
  "Harvested {harvested} · Sold {sold}": {"st":"Kotutswe {harvested} · Rekisitswe {sold}","ve":"Zwo kaṋwaho {harvested} · Zwo rengiswaho {sold}","ts":"Leswi tshoveriweke {harvested} · Leswi xavisiweke {sold}"},
  "Harvested {harvested}, sold {sold} — {kept} kept: eaten at home, given away, fed out, saved for seed or spoiled.": {"st":"Kotutswe {harvested}, rekisitswe {sold} — {kept} e setseng polasing: e jelwe hae, e newe ba bang, e fepilwe diphoofolo, e bolokelwe peo kapa e senyehile.","ve":"Zwo kaṋwaho {harvested}, zwo rengiswaho {sold} — {kept} zwo salaho bulasini: zwo ḽiwa hayani, zwo ṋewa vhaṅwe, zwo ṋewa zwifuwo, zwo vhulungelwa mbeu kana zwo vhifha.","ts":"Leswi tshoveriweke {harvested}, leswi xavisiweke {sold} — leswi tshameke i {kept}: leswi dyiweke ekaya, leswi nyikiweke van'wana, leswi dyisiweke swifuwo, leswi hlayisiweke ku va mbewu kumbe leswi bolekeke."},
