  "View invoice": {"st":"Sheba invoyese","ve":"Vhonani invoisi","ts":"Vona invoyisi"},
  "View invoice for": {"st":"Sheba invoyese ya","ve":"Vhonani invoisi ya","ts":"Vona invoyisi ya"},
