  "shops about R{wholesale}/kg · direct/farm gate about R{retail}/kg.": {"zu":"izitolo cishe ngu-R{wholesale}/kg · ukudayisa ngqo/epulazini cishe ngu-R{retail}/kg.","st":"mabenkele a ka bang R{wholesale}/kg · thekiso ya ka kotloloho/heke ya polasi e ka bang R{retail}/kg.","ve":"zwitoroni tsini na R{wholesale}/kg · u rengisa ṋoṋe/bulasini tsini na R{retail}/kg.","ts":"switolo ku ringanyeta R{wholesale}/kg · ku xavisa hi ku kongoma/epurasini ku ringanyeta R{retail}/kg."},
  "shops/bulk about R{price}/kg": {"zu":"izitolo/ngobuningi cishe ngu-R{price}/kg","st":"mabenkele/bongata e ka bang R{price}/kg","ve":"zwitoroni/u rengisa nga vhunzhi tsini na R{price}/kg","ts":"switolo/hi vunyingi kwalomu ka R{price}/kg"},
